class _WaxLocalizationsDelegate
    extends LocalizationsDelegate<WaxLocalizations> {
  const _WaxLocalizationsDelegate();

  @override
  Future<WaxLocalizations> load(Locale locale) {
    return SynchronousFuture<WaxLocalizations>(lookupWaxLocalizations(locale));
  }

  @override
  bool isSupported(Locale locale) =>
      <String>['en', 'es'].contains(locale.languageCode);

  @override
  bool shouldReload(_WaxLocalizationsDelegate old) => false;
}

WaxLocalizations lookupWaxLocalizations(Locale locale) {
  // Lookup logic when only language code is specified.
  switch (locale.languageCode) {
    case 'en':
      return WaxLocalizationsEn();
    case 'es':
      return WaxLocalizationsEs();
  }

  throw FlutterError(
    'WaxLocalizations.delegate failed to load unsupported locale "$locale". This is likely '
    'an issue with the localizations generation tool. Please file an issue '
    'on GitHub with a reproducible sample app and the gen-l10n configuration '
    'that was used.',
  );
}
